5, 66239, 61165, 62871, 18204, 101598, 161146, 178509, 170442, 31420, 119199, 15993, 35205, 45885, 20345, 187735, 19766, 350082, 190438, 12812, 235458, 60206, 71863, 257446, 25975, 65892, 12334, 169376, 536530, 60537, 8471, 162666, 209293, 13475, 117667, 7638], reverse=True)\n\n# Alternative method: Using OLS regression\n# Zipf's law: f(r) ~ 1/r^s  \n# In log form: log(f) = log(C) - s*log(r)\n# So: s = -slope of log(r) vs log(f)\n\nn = len(values)\nlog_r = [math.log(r+1) for r in range(n)]  # log(rank)\nlog_f = [math.log(f) for f in values]       # log(frequency)\n\n# OLS\nsum_log_r = sum(log_r)\nsum_log_f = sum(log_f)\nsum_log_r_log_f = sum(log_r[i] * log_f[i] for i in range(n))\nsum_log_r_sq = sum(r**2 for r in log_r)\n\nbeta = (n * sum_log_r_log_f - sum_log_r * sum_log_f) / (n * sum_log_r_sq - sum_log_r**2)\nalpha = -beta\n\nprint(f\"Method 1 (OLS): Zipf exponent = {alpha:.6f}\")\n\n# Method 2: Using Zipf's law directly - the harmonic mean of rank ratios\n# For a perfect Zipf distribution: r * f(r) = constant\n# So we can estimate s using the average of r * f(r)\n\n# Actually, let's try the maximum likelihood estimator for the discrete Pareto/Zipf distribution\n# For Zipf distribution: s = n / sum(log(r_i / r_1)) where r_i are the ranks\n\n# Actually, there's another method: the MLE for the exponent is:\n# s_hat = n / sum(log(i))\n# But this assumes a specific form\n\n# Let me use the simple regression approach but verify with another method\n# Another common approach: s = 1 / (mean(log(rank)) - log(rank_1)) for normalized values\n\n# Let's just verify using a simpler regression: value vs 1/rank^alpha form\n# Using log-log regression as above is standard\n\nprint(f\"\\nRounded to 3 decimal places: {round(alpha, 3)}\")\n\n# Also verify by checking the R-squared\ny_mean = sum_log_f / n\nss_tot = sum((y - y_mean)**2 for y in log_f)\nss_res = sum((log_f[i] - (beta * log_r[i] + (sum_log_f - beta * sum_log_r)/n))**2 for i in range(n))\nr_squared = 1 - ss_res/ss_tot\npr